def lcm(a, b):
    """
    Computes the least common multiple of two numbers a and b using the Euclidean algorithm.

    Parameters:
    a (int): First positive integer.
    b (int): Second positive integer.

    Returns:
    int: The least common multiple of a and b.
    """
    while True:
        if a % b == 0:
            return abs(a) * b // math.gcd(abs(a), b)
        elif b % a == 0:
            return abs(a) * b // math.gcd(a, b)
        else:
            a += 1

def longest_common_prefix(strs):
    """
    Returns the longest common prefix of all strings in the given list.

    :param strs: List of strings
    :return: Longest common prefix string
    """
    if not strs:
        return ""

    min_str = min(strs, key=len)
    for i, char in enumerate(min_str):
        for other_char in strs:
            if other_char[i] != char:
                return min_str[:i] + min_str[i+1:]

    return min_str

