def longest_common_prefix(strs):
    """
    Finds the longest common prefix string amongst an array of strings.

    :param strs: List[str] - An array of strings.
    :return: str - The longest common prefix string or an empty string if no common prefix exists.
    """
    if not strs:
        return ""

    shortest = min(strs, key=len)

    for i in range(min(len(shortest), len(strs[0]))):
        current = shortest[i]

        for j in range(1, len(strs)):
            if shortest[j-1] != current:
                break

        else:
            return shortest[:i]

    return shortest

def longest_common_prefix(strs):
    """
    Finds the longest common prefix string amongst an array of strings.

    :param strs: List[str] - A list of strings.
    :return: str - The longest common prefix string or an empty string if no common prefix exists.
    """
    if not strs:
        return ""

    shortest = min(strs, key=len)

    for i in range(min(len(shortest), len(next(iter(strs))))):
        current = next(iter(strs))
        while current[:i+1] != shortest[:i+1]:
            current = next(iter(strs))

        if current == shortest:
            break

    return shortest[:i+1]

