def longest_common_prefix(strs):
    """
    Finds the longest common prefix string amongst an array of strings.

    :param strs: List[str] - An array of strings.
    :return: str - The longest common prefix string or an empty string if no common prefix exists.
    """
    if not strs:
        return ""

    shortest = min(strs, key=len)

    for i in range(min(len(shortest), len(next(iter(strs))))):
        char1 = shortest[i]
        char2 = next(iter(strs)).char

        if char1 != char2 and (char1 == '' or char2 == ''):
            break

        if char1 == char2:
            continue

        while True:
            char3 = next((c for c in strs if c[:i] == char1), None)

            if char3 is None:
                break

            if char3 == char2:
                break

            shortest = char3

    return shortest

