def remove_duplicates(lst):
    """
    Removes duplicates from the given list of integers and returns a new list with unique elements sorted in ascending order.

    :param lst: List of integers
    :return: Sorted list of unique integers
    """
    seen = set()
    result = []
    for item in lst:
        if item not in seen:
            result.append(item)
            seen.add(item)
    return sorted(result)

def caesar(s, k):
    """
    Shifts each lowercase letter in s forward by k positions, wrapping around the alphabet.

    Parameters:
    s (str): The input string to be shifted.
    k (int): The number of positions to shift each lowercase letter.

    Returns:
    str: The resulting string after shifting.
    """
    def shift_char(c, k):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + k) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') + k) % 26 + ord('A'))
        else:
            raise ValueError("Invalid character")

    return ''.join(shift_char(c, k) for c in s)

