def longest_common_prefix(strs):
    """
    Finds the longest common prefix amongst an array of strings.

    :param strs: List of strings
    :return: Longest common prefix string
    """
    if not strs:
        return ""

    min_str = min(strs)
    max_str = max(strs)

    for i in range(len(min_str)):
        while min_str[i] != max_str[i]:
            if min_str[:i+1] == max_str[:i+1]:
                return min_str[:i+1]
            else:
                min_str = min_str[i+1:]

    return min_str

