def flatten(lst):
    """
    Flattens a nested list into a single-level list without using built-in functions like len, str, etc.

    :param lst: List of lists to be flattened.
    :return: A single-level list containing all elements from the nested lists.
    """
    result = []
    for item in lst:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def word_count(s):
    """
    Returns a dictionary with words as keys and their counts as values.

    :param s: A string containing words separated by spaces.
    :return: A dictionary with words as keys and their counts as values.
    """
    words = s.split()
    count_dict = {}
    for word in words:
        if word in count_dict:
            count_dict[word] += 1
        else:
            count_dict[word] = 1
    return count_dict

def longest_common_prefix(strs):
    """
    Finds the longest common prefix string amongst an array of strings.

    :param strs: List of strings
    :return: Longest common prefix string or empty string if no such prefix exists
    """
    if not strs:
        return ""

    min_str = min(strs)
    for i, char in enumerate(min_str):
        for other_char in strs[i+1:]:
            if other_char != char and (other_char == '.' or char == '.') and len(set(other_char)) > 1:
                return min_str[:i] + other_char

    return ""

